15. /**
16.  * Extracts {@link CodeownersRule}s from CODEOWNERS file content by driving the
17.  * shared {@link CodeownersLexer} and grouping pattern + owner tokens on the
18.  * same line.
19.  *
20.  * <p>This is the only place where lexer tokens are translated into the rule
21.  * model — keeping it here avoids duplicating the lexer's awareness of token
22.  * categories elsewhere.
23.  *
24.  * <p>GitLab section headers may declare <em>default owners</em> on the header
25.  * line, e.g. {@code [Backend][2] @org/backend @alice}. Those owners apply to
26.  * every rule in the section that does not list owners of its own; a rule that
27.  * does list owners overrides the default entirely. A section's scope runs from
28.  * its header to the next header (or end of file), and a header with no owners
29.  * clears any previously inherited default. The owners stored on each
30.  * {@link CodeownersRule} are therefore the <em>effective</em> owners, after
31.  * inheritance has been applied.
32.  *
33.  * <p>A section's optional approval count ({@code [Backend][2]}) is likewise
34.  * carried onto every rule in that section as {@link CodeownersRule#approvalCount()}.
35.  */
36. public final class CodeownersRuleParser {
37. 
38.   private CodeownersRuleParser() {
39.   }
40. 
41.   /**
42.    * Parse {@code content}. {@code source} is attached to each rule for navigation.
43.    */
44.   public static @NotNull List<CodeownersRule> parse(@NotNull CharSequence content,
45.                                                     @Nullable VirtualFile source) {
46.     if (content.isEmpty()) return Collections.emptyList();
47. 
48.     CodeownersLexer lexer = new CodeownersLexer();
49.     lexer.start(content, 0, content.length(), 0);
50. 
51.     List<CodeownersRule> rules = new ArrayList<>();
52.     String pendingPattern = null;
53.     int pendingLine = -1;
54.     List<String> pendingOwners = null;
55. 
56.     // Default owners declared on the current section header line, inherited by
57.     // rules in the section that name no owners of their own. Reset by each new
58.     // section header.
59.     List<String> sectionDefaultOwners = Collections.emptyList();
60.     // Approval count declared on the current section header (e.g. [Backend][2]),
61.     // or null when the section declares none. Also reset by each new header.
62.     Integer sectionApprovalCount = null;
63.     // The current section header as a whole, or null before the first header.
64.     // Carried onto each rule so an explanation can describe inheritance.
65.     CodeownersSection currentSection = null;
66.     // While true we are accumulating the section header line; its owners become
67.     // the section default and its [N] becomes the approval count once it ends.
68.     boolean inSectionHeader = false;
69.     List<String> headerOwners = null;
70.     Integer headerApprovalCount = null;
71.     String headerName = null;
72.     boolean headerOptional = false;
73. 
74.     while (lexer.getTokenType() != null) {
75.       IElementType type = lexer.getTokenType();
76.       int start = lexer.getTokenStart();
77.       int end = lexer.getTokenEnd();
78. 
79.       if (type == CodeownersTokenTypes.SECTION_HEADER) {
80.         if (pendingPattern != null) {
81.           rules.add(buildRule(pendingPattern, pendingOwners, sectionDefaultOwners, source, pendingLine, sectionApprovalCount, currentSection));
82.           pendingPattern = null;
83.           pendingOwners = null;
84.         }
85.         // Begin collecting the new section header; the previous section's
86.         // default owners and approval count no longer apply once a header is seen.
87.         String headerText = content.subSequence(start, end).toString();
88.         headerOptional = headerText.startsWith("^");
89.         headerName = sectionName(headerText);
90.         inSectionHeader = true;
91.         headerOwners = new ArrayList<>();
92.         headerApprovalCount = null;
93.       } else if (type == CodeownersTokenTypes.PATTERN) {
94.         if (pendingPattern != null) {
95.           rules.add(buildRule(pendingPattern, pendingOwners, sectionDefaultOwners, source, pendingLine, sectionApprovalCount, currentSection));
96.         }
97.         pendingPattern = content.subSequence(start, end).toString();
98.         pendingLine = lineNumberOf(content, start);
99.         pendingOwners = new ArrayList<>();
100.       } else if (type == CodeownersTokenTypes.APPROVAL_COUNT && inSectionHeader) {
101.         headerApprovalCount = parseApprovalCount(content.subSequence(start, end).toString());
102.       } else if (isOwnerToken(type)) {
103.         if (inSectionHeader) {
104.           headerOwners.add(content.subSequence(start, end).toString());
105.         } else if (pendingPattern != null) {
106.           pendingOwners.add(content.subSequence(start, end).toString());
107.         }
108.       } else if (type == TokenType.WHITE_SPACE && containsNewline(content, start, end)) {
109.         if (inSectionHeader) {
110.           sectionDefaultOwners = List.copyOf(headerOwners);
111.           sectionApprovalCount = headerApprovalCount;
112.           currentSection = new CodeownersSection(
113.                   headerName != null ? headerName : "",
114.                   headerOptional, sectionDefaultOwners, sectionApprovalCount);
115.           inSectionHeader = false;
116.           headerOwners = null;
117.           headerApprovalCount = null;
118.           headerName = null;
119.           headerOptional = false;
120.         } else if (pendingPattern != null) {
121.           rules.add(buildRule(pendingPattern, pendingOwners, sectionDefaultOwners, source, pendingLine, sectionApprovalCount, currentSection));
122.           pendingPattern = null;
123.           pendingOwners = null;
124.         }
125.       }
126. 
127.       lexer.advance();
128.     }
129.     if (pendingPattern != null) {
130.       rules.add(buildRule(pendingPattern, pendingOwners, sectionDefaultOwners, source, pendingLine, sectionApprovalCount, currentSection));
131.     }
132.     return rules;
133.   }
134. 
135.   /**
136.    * Extracts the name from a {@code SECTION_HEADER} token such as
137.    * {@code [Backend]} or {@code ^[Backend]} — the text between the brackets.
138.    */
139.   public static @NotNull String sectionName(@NotNull String headerText) {
140.     int open = headerText.indexOf('[');
141.     int close = headerText.indexOf(']', open + 1);
142.     if (open < 0 || close < 0) return "";
143.     return headerText.substring(open + 1, close).trim();
144.   }
145. 
146.   /**
147.    * Parses the integer inside an {@code APPROVAL_COUNT} token (e.g. {@code [2]}),
148.    * returning {@code null} for a missing or non-numeric value.
149.    */
150.   private static @Nullable Integer parseApprovalCount(@NotNull String token) {
151.     String t = token.trim();
152.     if (t.startsWith("[")) t = t.substring(1);
153.     if (t.endsWith("]")) t = t.substring(0, t.length() - 1);
154.     try {
155.       int n = Integer.parseInt(t.trim());
156.       return n >= 0 ? n : null;
157.     } catch (NumberFormatException ignored) {
158.       return null;
159.     }
160.   }
161. 
162.   /**
163.    * Builds a rule, applying section inheritance: a rule that declares no owners
164.    * of its own takes the enclosing section's default owners, and that fact is
165.    * recorded via {@link CodeownersRule#ownersInherited()} for later explanation.
166.    */
167.   private static @NotNull CodeownersRule buildRule(@NotNull String pattern,
168.                                                    @NotNull List<String> ruleOwners,
169.                                                    @NotNull List<String> sectionDefaultOwners,
170.                                                    @Nullable VirtualFile source,
171.                                                    int lineNumber,
172.                                                    @Nullable Integer approvalCount,
173.                                                    @Nullable CodeownersSection section) {
174.     boolean inherited = ruleOwners.isEmpty() && !sectionDefaultOwners.isEmpty();
175.     List<String> owners = inherited ? sectionDefaultOwners : ruleOwners;
176.     return new CodeownersRule(
177.             pattern,
178.             List.copyOf(owners),
179.             CodeownersGlob.compile(pattern),
180.             source,
181.             lineNumber,
182.             approvalCount,
183.             section,
184.             inherited);
185.   }
186. 
187.   /**
188.    * Whether {@code type} is one of the lexer's owner categories — user, team,
189.    * role or e-mail. Shared so that features working on owner tokens (owner
190.    * refactoring, for one) classify them exactly as the rule model does.
191.    */
192.   public static boolean isOwnerToken(IElementType type) {
193.     return type == CodeownersTokenTypes.USER_OWNER
194.             || type == CodeownersTokenTypes.TEAM_OWNER
195.             || type == CodeownersTokenTypes.ROLE_OWNER
196.             || type == CodeownersTokenTypes.EMAIL_OWNER;
197.   }
198. 
199.   private static boolean containsNewline(CharSequence content, int start, int end) {
200.     for (int i = start; i < end; i++) {
201.       char c = content.charAt(i);
202.       if (c == '\n' || c == '\r') return true;
203.     }
204.     return false;
205.   }
206. 
207.   private static int lineNumberOf(CharSequence content, int offset) {
208.     int line = 0;
209.     for (int i = 0; i < offset && i < content.length(); i++) {
210.       if (content.charAt(i) == '\n') line++;
211.     }
212.     return line;
213.   }
214. }
