59.   private static @Nullable Located locateFor(@NotNull VirtualFile file) {
60.     VirtualFile dir = file.isDirectory() ? file : file.getParent();
61.     while (dir != null) {
62.       for (String candidate : CANDIDATE_PATHS) {
63.         VirtualFile vf = dir.findFileByRelativePath(candidate);
64.         if (vf != null && vf.isValid() && !vf.isDirectory()) {
65.           return new Located(vf, dir);
66.         }
67.       }
68.       dir = dir.getParent();
69.     }
70.     return null;
