73.   private static @Nullable String relativizeAgainst(@NotNull String filePath, @NotNull String rootPath) {
74.     if (filePath.equals(rootPath)) return "";
75.     String prefix = rootPath.endsWith("/") ? rootPath : rootPath + "/";
