100.    * document state.
101.    */
102.   public @NotNull CodeownersOwnerResolution resolveOwners(@Nullable VirtualFile file) {
103.     if (file == null || project.isDisposed()) return CodeownersOwnerResolution.NONE;
104.     Located located = locateFor(file);
105.     if (located == null) return CodeownersOwnerResolution.NONE;
106.     String relativePath = relativizeAgainst(file.getPath(), located.root.getPath());
107.     if (relativePath == null) return CodeownersOwnerResolution.NONE;
108. 
109.     List<CodeownersRule> matching = matchingRules(getRules(located.codeownersFile), relativePath);
110.     // Last-match-wins: the last matching rule in file order governs.
111.     return matching.isEmpty()
112.             ? CodeownersOwnerResolution.NONE
113.             : new CodeownersOwnerResolution(matching.get(matching.size() - 1));
114.   }
115. 
116.   /**
117.    * Explains the CODEOWNERS ownership of {@code file}: every rule that matches
118.    * it (in evaluation order) and which one wins. Shares its matching pass with
119.    * {@link #resolveOwners} via {@link #matchingRules}, so the effective owner in
120.    * the returned {@link OwnershipExplanation} always agrees with the status bar
121.    * widget and owner-lookup logic.
122.    *
123.    * <p>Must be called under a read action — it accesses VFS and possibly
124.    * document state.
125.    */
126.   public @NotNull OwnershipExplanation explain(@NotNull VirtualFile file) {
127.     if (project.isDisposed()) return OwnershipExplanation.noCodeowners(file);
128.     Located located = locateFor(file);
129.     if (located == null) return OwnershipExplanation.noCodeowners(file);
130.     String relativePath = relativizeAgainst(file.getPath(), located.root.getPath());
131.     if (relativePath == null) return OwnershipExplanation.noCodeowners(file);
132. 
133.     List<CodeownersRule> matching = matchingRules(getRules(located.codeownersFile), relativePath);
134.     return OwnershipExplanation.of(file, relativePath, located.codeownersFile, matching);
135.   }
136. 
137.   /**
138.    * Resolves the CODEOWNERS context for {@code file}: the governing CODEOWNERS
139.    * file, the file's path relative to that CODEOWNERS file's root, and the
140.    * parsed rules. Returns {@code null} when no CODEOWNERS file is reachable.
141.    *
142.    * <p>Used by owner-suggestion: it needs the repo-relative path (to build a
143.    * new rule and to score path proximity) and the rules, all anchored to the
144.    * same root the resolver uses. Must be called under a read action.
145.    */
146.   public @Nullable FileContext fileContext(@Nullable VirtualFile file) {
147.     if (file == null || project.isDisposed()) return null;
148.     Located located = locateFor(file);
149.     if (located == null) return null;
150.     String relativePath = relativizeAgainst(file.getPath(), located.root.getPath());
151.     if (relativePath == null || relativePath.isEmpty()) return null;
152.     return new FileContext(located.codeownersFile, relativePath, getRules(located.codeownersFile));
153.   }
154. 
155.   /**
156.    * @return the CODEOWNERS file that was used for the most recent resolution, or {@code null}.
157.    */
158.   public @Nullable VirtualFile getCodeownersFile() {
159.     Cache c = cache;
160.     return c == null ? null : c.sourceFile;
161.   }
162. 
163.   private @NotNull List<CodeownersRule> getRules(@NotNull VirtualFile codeownersFile) {
164.     long stamp = currentStamp(codeownersFile);
165.     Cache existing = cache;
166.     if (existing != null && existing.sourceFile.equals(codeownersFile) && existing.stamp == stamp) {
167.       return existing.rules;
168.     }
169.     CharSequence content = readContent(codeownersFile);
170.     List<CodeownersRule> rules = CodeownersRuleParser.parse(content, codeownersFile);
171.     cache = new Cache(codeownersFile, stamp, rules);
172.     return rules;
173.   }
174. 
175.   private @NotNull CharSequence readContent(@NotNull VirtualFile file) {
176.     Document doc = FileDocumentManager.getInstance().getDocument(file);
177.     if (doc != null) return doc.getCharsSequence();
178.     try {
179.       return new String(file.contentsToByteArray(), file.getCharset());
180.     } catch (Exception ignored) {
181.       return "";
182.     }
183.   }
184. 
185.   /**
186.    * Uses the document stamp when an editor has the file open (catches
187.    * unsaved edits), and the VFS stamp otherwise.
188.    */
189.   private long currentStamp(@NotNull VirtualFile file) {
190.     Document doc = FileDocumentManager.getInstance().getCachedDocument(file);
191.     return doc != null ? doc.getModificationStamp() : file.getModificationStamp();
192.   }
193. 
194.   private record Located(@NotNull VirtualFile codeownersFile, @NotNull VirtualFile root) {
195.   }
196. 
197.   /**
198.    * The CODEOWNERS context for a target file: its governing CODEOWNERS file, its
199.    * repo-relative path, and the parsed rules.
200.    */
201.   public record FileContext(@NotNull VirtualFile codeownersFile,
202.                             @NotNull String relativePath,
203.                             @NotNull List<CodeownersRule> rules) {
204.   }
205. 
206.   private record Cache(@NotNull VirtualFile sourceFile, long stamp, @NotNull List<CodeownersRule> rules) {
207.   }
208. }
