2. 
3. import org.jetbrains.annotations.NotNull;
4. 
5. import java.util.regex.Pattern;
6. 
7. /**
8.  * Compiles a CODEOWNERS glob pattern into an anchored {@link Pattern} that
9.  * matches forward-slash separated, project-relative file paths (no leading
10.  * {@code /}).
11.  *
12.  * <p>The implemented semantics follow GitHub's documented rules, which are a
13.  * subset of {@code .gitignore}:
14.  * <ul>
15.  *   <li>{@code *} — matches any run of characters within a single path
16.  *       segment (does not cross {@code /}).</li>
17.  *   <li>{@code **} — matches across path segments, including zero segments.
18.  *       {@code foo/**} matches any descendant of {@code foo}.</li>
19.  *   <li>{@code ?} — matches exactly one non-{@code /} character.</li>
20.  *   <li>A pattern starting with {@code /} is anchored to the repo root.</li>
21.  *   <li>A pattern containing {@code /} (but not at the start) is also anchored
22.  *       to the repo root — this matches GitHub's behavior and differs from
23.  *       gitignore.</li>
24.  *   <li>A pattern with no {@code /} (e.g. {@code *.java}) matches files with
25.  *       that name at any depth.</li>
26.  *   <li>A pattern ending with {@code /} matches that directory and everything
27.  *       under it.</li>
28.  *   <li>A pattern that matches a directory implicitly matches everything
29.  *       under it as well.</li>
30.  * </ul>
31.  *
32.  * <p>A leading {@code !} (GitLab negation) is stripped here; the caller decides
33.  * how to use negation when resolving ownership. Last-match-wins resolution
34.  * makes negation rarely needed in practice.
35.  */
36. public final class CodeownersGlob {
37. 
38.   private CodeownersGlob() {
39.   }
40. 
41.   /**
42.    * Compile {@code glob} into an anchored regex. Never returns {@code null}.
43.    */
44.   public static @NotNull Pattern compile(@NotNull String glob) {
45.     String g = glob;
46.     if (g.startsWith("!")) g = g.substring(1);
47. 
48.     boolean rooted = g.startsWith("/");
49.     if (rooted) g = g.substring(1);
50. 
51.     boolean dirOnly = g.endsWith("/");
52.     if (dirOnly) g = g.substring(0, g.length() - 1);
53. 
54.     boolean hasSlash = g.contains("/");
55. 
56.     StringBuilder re = new StringBuilder();
57.     re.append("^");
58.     // If the pattern has no slash and is not rooted, it can match a basename
59.     // at any depth. Otherwise, the pattern is anchored to the repo root.
60.     if (!rooted && !hasSlash) {
61.       re.append("(?:.*/)?");
62.     }
63.     appendGlob(re, g);
64.     if (dirOnly) {
65.       // Directory-only pattern: match anything beneath that directory.
66.       re.append("/.*");
67.     } else {
68.       // Any rule that matches a directory also matches its contents.
69.       re.append("(?:/.*)?");
70.     }
71.     re.append("$");
72.     return Pattern.compile(re.toString());
73.   }
74. 
75.   private static void appendGlob(StringBuilder re, @NotNull String g) {
76.     int i = 0;
77.     int n = g.length();
78.     while (i < n) {
79.       char c = g.charAt(i);
80.       if (c == '*') {
81.         boolean doubleStar = i + 1 < n && g.charAt(i + 1) == '*';
82.         if (doubleStar) {
83.           // Consume "**" and an optional trailing "/" so that "foo/**/bar" or
84.           // "foo/**" both behave as "any depth, including zero".
85.           re.append(".*");
86.           i += 2;
87.           if (i < n && g.charAt(i) == '/') i++;
88.         } else {
89.           re.append("[^/]*");
90.           i++;
91.         }
92.       } else if (c == '?') {
93.         re.append("[^/]");
94.         i++;
95.       } else if (c == '\\' && i + 1 < n) {
96.         // Escape sequence — emit the next char as a literal.
97.         re.append(Pattern.quote(String.valueOf(g.charAt(i + 1))));
98.         i += 2;
99.       } else if ("\\.^$+|(){}[]".indexOf(c) >= 0) {
100.         re.append('\\').append(c);
101.         i++;
102.       } else {
103.         re.append(c);
104.         i++;
105.       }
106.     }
107.   }
108. }
